def choose_move(observation):
    # Defensive access to observation fields
    grid = observation.get('grid', {})
    unit = observation.get('unit', {})
    message = observation.get('message', '')
    turn = observation.get('turn', 0)

    # Determine current position
    x = unit.get('x', 0)
    y = unit.get('y', 0)

    # Identify goal type based on message or context (simple heuristics)
    if 'resource' in message.lower() or 'collect' in message.lower():
        goal_type = 'resource'
    elif 'evade' in message.lower() or 'danger' in message.lower():
        goal_type = 'evade'
    elif 'territory' in message.lower() or 'control' in message.lower():
        goal_type = 'territory'
    else:
        # Default behavior if no specific goal indicated
        goal_type = 'default'

    # Helper function to find closest target of a given type
    def find_closest_target(targets):
        min_dist = float('inf')
        target_pos = None
        for t in targets:
            tx, ty = t.get('x'), t.get('y')
            if tx is None or ty is None:
                continue
            dist = abs(tx - x) + abs(ty - y)
            if dist < min_dist:
                min_dist = dist
                target_pos = (tx, ty)
        return target_pos

    # Identify relevant positions based on goal
    targets = []

    # Extract resource positions for resource collection
    if goal_type == 'resource' and 'resources' in grid:
        targets = grid.get('resources', [])
    # Extract enemy positions for pursuit/evasion
    elif goal_type in ('evade', 'pursuit'):
        if 'enemies' in grid:
            enemy_positions = grid.get('enemies', [])
            # For evasion, target closest enemy to keep distance
            # For pursuit, target closest enemy to approach
            targets = enemy_positions
    # Extract territory boundaries or control points if relevant
    elif goal_type == 'territory':
        if 'territory_points' in grid:
            targets = grid.get('territory_points', [])
    else:
        # Default: no specific targets
        targets = []

    target = find_closest_target(targets) if targets else None

    # Decide move based on goal
    dx, dy = 0, 0
    if target:
        tx, ty = target
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
    else:
        # No target: simple wandering or hold position
        dx, dy = 0, 0

    # For evading enemies, move away if an enemy is very close
    if goal_type == 'evade' and 'enemies' in grid:
        for enemy in grid.get('enemies', []):
            ex = enemy.get('x')
            ey = enemy.get('y')
            if ex is None or ey is None:
                continue
            dist = abs(ex - x) + abs(ey - y)
            if dist <= 2:
                # Move in opposite direction
                if ex > x:
                    dx = -1
                elif ex < x:
                    dx = 1
                if ey > y:
                    dy = -1
                elif ey < y:
                    dy = 1
                break

    # Clip dx, dy to -1, 0, 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]
